mapper.select:
SELECT STYLE_SEQ
  FROM wo_cell_style_master
 WHERE WORKBOOK_SEQ = #{workbookSeq}
   AND STYLE_CODE   = #{styleCode}
   AND DEL_DATETIME IS NULL

mapper.insert:
INSERT INTO wo_cell_style_master (
    WORKBOOK_SEQ, STYLE_CODE, STYLE_VALUE, INPUT_DATETIME, INPUT_USER
) VALUES (
    #{style.workbookSeq}, #{style.styleCode}, #{style.styleValue},
    CURRENT_TIMESTAMP, #{userKey}
)

INSERT INTO wo_cell_style_master (
    WORKBOOK_SEQ, STYLE_CODE, STYLE_VALUE, INPUT_DATETIME, INPUT_USER
) VALUES (
    #{style.workbookSeq}, #{style.styleCode},
    CAST(#{style.styleValue} AS jsonb),
    CURRENT_TIMESTAMP, #{userKey}
)
